-- Generated by model/lib/sql/generate.mjs. Loads FX Rate IN from cells/FX Rate IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/FX Rate IN.csv
INSERT INTO "FX Rate IN" SELECT coalesce(k0."Currency", fpabench_error('cells name a member Currency does not have: ' || c."Currency")), coalesce(k1."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Currency" k0 ON k0.name = c."Currency" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Currency", "Versions", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "FX Rate IN";
